insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','予約が見つからないお客様がチェックインに来ました。最も適切な対応はどれですか？','["予約がないので帰ってもらう", "予約票・名前・宿泊日を再確認し、空室があれば用意する", "他のホテルを紹介して終わる", "フロント責任者を呼ばずに放置する"]'::jsonb,1,'まず予約の再確認（名前・日付・経路）を行い、空室があれば案内します。満室なら近隣宿泊施設を手配します。',700,'2号 · 06 · 実技・ケース','Tamu datang check-in tapi reservasinya tidak ditemukan. Apa tindakan paling tepat?','Pertama periksa ulang reservasi (nama, tanggal, jalur pemesanan); kalau ada kamar kosong, sediakan. Kalau penuh, siapkan penginapan terdekat.','[{"k": "再確認", "b": "さいかくにん", "a": "pemeriksaan ulang"}, {"k": "空室", "b": "くうしつ", "a": "kamar kosong"}, {"k": "手配", "b": "てはい", "a": "pengaturan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','エアコンが故障した部屋に案内してしまいました。まず何をしますか？','["そのまま我慢してもらう", "すぐに謝罪し、修理か部屋替えを提案する", "修理費を請求する", "翌日に連絡する"]'::jsonb,1,'すぐに謝罪し、修理または空室への部屋替えを提案するのが基本です。',701,'2号 · 06 · 実技・ケース','Tamu sudah masuk kamar tapi AC-nya rusak. Apa langkah pertama?','Segera minta maaf lalu tawarkan perbaikan atau pindah kamar kosong.','[{"k": "故障", "b": "こしょう", "a": "kerusakan"}, {"k": "謝罪", "b": "しゃざい", "a": "permintaan maaf"}, {"k": "部屋替え", "b": "へやがえ", "a": "pindah kamar"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','隣室の騒音について苦情がありました。適切な対応はどれですか？','["お客様同士で話し合わせる", "すぐに謝罪し、状況確認のうえ部屋替えや注意を行う", "朝まで待つ", "警察を呼ぶ"]'::jsonb,1,'謝罪→状況確認→部屋替えや該当客への注意。夜間は特に迅速に動きます。',702,'2号 · 06 · 実技・ケース','Ada keluhan kebisingan dari kamar sebelah. Tindakan tepat?','Minta maaf → cek situasi → tawarkan pindah kamar atau tegur tamu terkait. Malam hari harus cepat.','[{"k": "騒音", "b": "そうおん", "a": "kebisingan"}, {"k": "苦情", "b": "くじょう", "a": "keluhan"}, {"k": "迅速", "b": "じんそく", "a": "cepat"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','食事提供後に食物アレルギーを申告されました。正しい対応はどれですか？','["自己判断で対応する", "すぐ提供を止め、料理長と責任者に共有し、症状を確認する", "何もせず様子を見る", "会計時に値引きする"]'::jsonb,1,'提供を中断し、調理場・責任者へ即共有。症状が重い場合は119番へ連絡します。',703,'2号 · 06 · 実技・ケース','Tamu baru mengaku punya alergi makanan setelah hidangan disajikan. Tindakan benar?','Hentikan penyajian, segera bagikan info ke dapur dan penanggung jawab, lalu cek gejala. Kalau berat, hubungi 119.','[{"k": "提供", "b": "ていきょう", "a": "penyajian"}, {"k": "共有", "b": "きょうゆう", "a": "berbagi info"}, {"k": "症状", "b": "しょうじょう", "a": "gejala"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','ダブルブッキングが発生しました。最初にすべきことはどれですか？','["お客様には黙っている", "早めに連絡して謝罪し、代替宿泊先を用意する", "料金を倍にする", "部屋を半分に分ける"]'::jsonb,1,'早い段階で連絡して謝罪し、近隣の代替宿泊先を手配します。',704,'2号 · 06 · 実技・ケース','Terjadi double booking. Apa yang pertama dilakukan?','Hubungi lebih awal, minta maaf, dan siapkan penginapan pengganti di sekitar.','[{"k": "重複予約", "b": "ちょうふくよやく", "a": "double booking"}, {"k": "代替", "b": "だいたい", "a": "pengganti"}, {"k": "早め", "b": "はやめ", "a": "lebih awal"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','満室の日に直接来館したお客様への対応はどれですか？','["玄関で断るだけ", "満室であることを丁寧に伝え、近隣施設を紹介する", "ロビーで待たせる", "割引して泊める"]'::jsonb,1,'満室を丁寧に説明し、近隣施設の紹介やタクシー手配などで支援します。',705,'2号 · 06 · 実技・ケース','Tamu walk-in datang saat hotel penuh. Bagaimana sebaiknya?','Jelaskan dengan sopan bahwa penuh, lalu bantu dengan rekomendasi hotel terdekat atau taksi.','[{"k": "満室", "b": "まんしつ", "a": "penuh"}, {"k": "丁寧", "b": "ていねい", "a": "sopan"}, {"k": "紹介", "b": "しょうかい", "a": "merekomendasikan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','館内でお客様が急病になりました。最初にすることはどれですか？','["水を渡して寝かせる", "意識と呼吸を確認し、119番へ連絡して救急を要請する", "家族に連絡するまで待つ", "部屋に戻す"]'::jsonb,1,'意識・呼吸を確認し、すぐ119番（救急）へ連絡。応急処置は指示に従います。',706,'2号 · 06 · 実技・ケース','Tamu tiba-tiba sakit di hotel. Langkah pertama?','Cek kesadaran dan napas, lalu segera telepon 119 (ambulans). Ikuti instruksi untuk pertolongan awal.','[{"k": "急病", "b": "きゅうびょう", "a": "sakit mendadak"}, {"k": "意識", "b": "いしき", "a": "kesadaran"}, {"k": "救急", "b": "きゅうきゅう", "a": "gawat darurat"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','火災報知器が作動しました。適切な行動はどれですか？','["誤報と決めつけて止める", "現場確認し、火災なら初期消火と避難誘導、119番通報", "全員を部屋に戻す", "エレベーターで避難させる"]'::jsonb,1,'現場確認→初期消火→避難誘導→119番。エレベーターは使わず非常階段を使います。',707,'2号 · 06 · 実技・ケース','Alarm kebakaran berbunyi. Tindakan tepat?','Cek lokasi → pemadaman awal → pandu evakuasi → telepon 119. Gunakan tangga darurat, jangan lift.','[{"k": "作動", "b": "さどう", "a": "berbunyi/aktif"}, {"k": "避難誘導", "b": "ひなんゆうどう", "a": "panduan evakuasi"}, {"k": "非常階段", "b": "ひじょうかいだん", "a": "tangga darurat"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','外国人客がパスポートを紛失しました。正しい対応はどれですか？','["自分で探させる", "状況を確認し、警察への届出と大使館・領事館の案内を行う", "チェックアウトさせる", "罰金を請求する"]'::jsonb,1,'遺失届は警察、渡航書類は大使館・領事館。宿泊記録の写しは法律で保管が必要です。',708,'2号 · 06 · 実技・ケース','Tamu asing kehilangan paspor. Tindakan yang benar?','Cek situasi, arahkan lapor polisi dan hubungi kedutaan/konsulat. Salinan data menginap wajib disimpan.','[{"k": "紛失", "b": "ふんしつ", "a": "kehilangan"}, {"k": "届出", "b": "とどけで", "a": "laporan"}, {"k": "大使館", "b": "たいしかん", "a": "kedutaan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','チェックアウト時、カード決済が承認されませんでした。適切な対応はどれですか？','["そのまま見送る", "別の支払い方法を丁寧に提案し、責任者に相談する", "警察を呼ぶ", "二重に請求する"]'::jsonb,1,'別のカードや現金など代替手段を丁寧に提案し、必要なら責任者へ相談します。',709,'2号 · 06 · 実技・ケース','Saat check-out, kartu kredit tamu ditolak. Bagaimana sebaiknya?','Tawarkan metode pembayaran lain dengan sopan, dan konsultasikan ke penanggung jawab bila perlu.','[{"k": "決済", "b": "けっさい", "a": "pembayaran"}, {"k": "承認", "b": "しょうにん", "a": "persetujuan"}, {"k": "提案", "b": "ていあん", "a": "menawarkan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様が貴重品を部屋に忘れて帰りました。正しい手順はどれですか？','["すぐ捨てる", "責任者の立会いで記録・保管し、本人確認のうえ返却する", "同僚に預ける", "宅配便で無記名で送る"]'::jsonb,1,'貴重品は責任者立会いのもと記録・保管し、本人確認後に返却します。',710,'2号 · 06 · 実技・ケース','Tamu meninggalkan barang berharga di kamar. Prosedur benar?','Catat dan simpan barang berharga dengan saksi penanggung jawab, lalu kembalikan setelah identitas tamu diverifikasi.','[{"k": "貴重品", "b": "きちょうひん", "a": "barang berharga"}, {"k": "保管", "b": "ほかん", "a": "penyimpanan"}, {"k": "返却", "b": "へんきゃく", "a": "pengembalian"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','満室の日にチェックアウト延長を希望されました。適切な対応はどれですか？','["無理にでも延長させる", "空室状況を確認し、不可なら近隣のデイユース等を案内する", "追加料金を取って部屋を確保する", "何も答えない"]'::jsonb,1,'空室状況を確認し、延長できない場合はデイユースや近隣施設を案内します。',711,'2号 · 06 · 実技・ケース','Tamu minta perpanjangan check-out padahal hotel penuh. Tindakan tepat?','Cek ketersediaan; kalau tidak bisa, tawarkan day-use atau fasilitas terdekat.','[{"k": "延長", "b": "えんちょう", "a": "perpanjangan"}, {"k": "状況", "b": "じょうきょう", "a": "situasi"}, {"k": "案内", "b": "あんない", "a": "mengarahkan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','レストランが満席のとき、予約なしの団体客が来ました。適切な対応はどれですか？','["黙って入れない", "待ち時間を伝え、別の時間帯や他店を提案する", "無理に詰め込む", "断って終わる"]'::jsonb,1,'待ち時間の目安を伝え、時間変更や系列店・近隣店を提案します。',712,'2号 · 06 · 実技・ケース','Restoran penuh dan datang rombongan tanpa reservasi. Bagaimana?','Sampaikan estimasi waktu tunggu, lalu tawarkan jam lain atau restoran lain.','[{"k": "満席", "b": "まんせき", "a": "penuh"}, {"k": "待ち時間", "b": "まちじかん", "a": "waktu tunggu"}, {"k": "提案", "b": "ていあん", "a": "menawarkan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様がスタッフに大声で怒っています。最初にすべきことはどれですか？','["言い返す", "静かな場所へ案内して話を聞き、謝意を示す", "無視する", "他の客に仲裁を頼む"]'::jsonb,1,'人目の少ない場所へ案内し、最後まで話を聞いたうえで謝意と対応策を示します。',713,'2号 · 06 · 実技・ケース','Tamu marah besar ke staf. Langkah pertama?','Ajak ke tempat tenang, dengarkan sampai selesai, lalu sampaikan permintaan maaf dan solusinya.','[{"k": "大声", "b": "おおごえ", "a": "suara keras"}, {"k": "案内", "b": "あんない", "a": "mengajak/mengarahkan"}, {"k": "謝意", "b": "しゃい", "a": "rasa maaf"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','館内が停電しました。優先すべき対応はどれですか？','["復旧作業だけを行う", "非常灯と避難経路を確認し、お客様の安全を確保して案内する", "料金を返金する", "SNSで告知する"]'::jsonb,1,'まず安全確保。非常灯・避難経路を確認し、お客様へ状況と指示を伝えます。',714,'2号 · 06 · 実技・ケース','Listrik hotel padam. Prioritas utama?','Utamakan keselamatan: cek lampu darurat dan jalur evakuasi, lalu beri tahu tamu situasi dan instruksinya.','[{"k": "停電", "b": "ていでん", "a": "mati listrik"}, {"k": "非常灯", "b": "ひじょうとう", "a": "lampu darurat"}, {"k": "安全", "b": "あんぜん", "a": "keselamatan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','大雪で交通機関が止まり、宿泊客のキャンセルが相次ぎました。適切な対応はどれですか？','["キャンセル料を全額請求する", "状況を確認し、規定に沿って柔軟にキャンセル・変更を案内する", "電話に出ない", "SNSだけ更新する"]'::jsonb,1,'交通状況を確認し、規定と判断に基づき柔軟にキャンセル・変更へ対応します。',715,'2号 · 06 · 実技・ケース','Salju lebat melumpuhkan transportasi dan banyak tamu membatalkan. Tindakan tepat?','Cek kondisi transportasi, lalu tangani pembatalan/perubahan secara fleksibel sesuai aturan.','[{"k": "大雪", "b": "おおゆき", "a": "salju lebat"}, {"k": "交通機関", "b": "こうつうきかん", "a": "transportasi"}, {"k": "柔軟", "b": "じゅうなん", "a": "fleksibel"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','従業員が体調不良で勤務中に倒れました。まず何をしますか？','["そのまま仕事を続けさせる", "安全な場所で休ませ、責任者へ報告し必要なら119番", "給料を差し引く", "誰にも言わない"]'::jsonb,1,'安全確保と報告が最優先。重症なら119番へ連絡します。',716,'2号 · 06 · 実技・ケース','Rekan kerja pingsan saat bertugas. Apa langkah pertama?','Bawa ke tempat aman, laporkan ke penanggung jawab, dan hubungi 119 bila berat.','[{"k": "体調不良", "b": "たいちょうふりょう", "a": "kondisi badan buruk"}, {"k": "報告", "b": "ほうこく", "a": "laporan"}, {"k": "優先", "b": "ゆうせん", "a": "prioritas"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様が分別ルールと違う場所にゴミを捨てました。正しい対応はどれですか？','["叱る", "やわらかく声をかけ、正しい分別方法を案内する", "何も言わない", "罰金を取る"]'::jsonb,1,'責めずに、やわらかい言葉で正しい分別を案内します。',717,'2号 · 06 · 実技・ケース','Tamu membuang sampah tidak sesuai pemilahan. Sikap tepat?','Tegur dengan lembut dan jelaskan cara pemilahan yang benar.','[{"k": "分別", "b": "ぶんべつ", "a": "pemilahan"}, {"k": "案内", "b": "あんない", "a": "menjelaskan"}, {"k": "やわらかい", "b": "やわらかい", "a": "lembut"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','禁煙室で喫煙していたお客様を見つけました。適切な対応はどれですか？','["黙認する", "禁煙であることを丁寧に伝え、喫煙所を案内する", "部屋から追い出す", "清掃費を二重に請求する"]'::jsonb,1,'丁寧に禁煙であることを伝え、喫煙所へ案内します。必要なら清掃費用を説明します。',718,'2号 · 06 · 実技・ケース','Tamu merokok di kamar non-smoking. Tindakan tepat?','Sampaikan dengan sopan bahwa kamar bebas asap, arahkan ke area merokok, dan jelaskan biaya pembersihan bila perlu.','[{"k": "禁煙", "b": "きんえん", "a": "bebas asap"}, {"k": "喫煙所", "b": "きつえんじょ", "a": "area merokok"}, {"k": "丁寧", "b": "ていねい", "a": "sopan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','会計明細の金額が違うと指摘されました。最初にすべきことはどれですか？','["間違いではないと言い張る", "明細を一緒に確認し、誤りがあれば訂正して謝罪する", "その場で返金だけする", "責任者を呼ばずに待たせる"]'::jsonb,1,'明細を一緒に確認し、誤りがあれば速やかに訂正・謝罪します。',719,'2号 · 06 · 実技・ケース','Tamu menyatakan nominal tagihan salah. Langkah pertama?','Periksa rincian bersama tamu; bila memang salah, segera perbaiki dan minta maaf.','[{"k": "明細", "b": "めいさい", "a": "rincian"}, {"k": "訂正", "b": "ていせい", "a": "koreksi"}, {"k": "指摘", "b": "してき", "a": "menunjukkan/menegur"}]'::jsonb);
